entries[418359] = { ["name"] = "Kampfvorteil ausnutzen", ["text"] = "Ersetzt Tigerklaue\nEure automatischen Waffenhandangriffe verringern die Abklingzeit Eurer Gebräue um 0.5 Sek. und blockieren das Chi Eures Ziels, was zusätzlich (22.2% der Angriffskraft) Naturschaden verursacht und Euren verursachten Schaden für 20 Sek. um 1% erhöht.\n\nBei Erreichen von 10 Stapeln verbraucht Euer nächster Einsatz von 'Tritt der aufgehenden Sonne' oder 'Fasshieb' sämtliche Stapel und wird ein zweites Mal mit 100% Effektivität eingesetzt. Dieser Bonusangriff kann Effekte anstelle von 'Tigerklaue' mit verringerter Effektivität auslösen." }
entries[418360] = { ["name"] = "Kampfvorteil ausnutzen", ["text"] = "Unbegrenzte Reichweite\nSofort\nEure automatischen Waffenhandangriffe verringern die Abklingzeit Eurer Gebräue um 0.5 Sek. und blockieren das Chi Eures Ziels, was zusätzlich (22.2% der Angriffskraft) Naturschaden verursacht und Euren verursachten Schaden für 20 Sek. um 1% erhöht.\n\nBei Erreichen von 10 Stapeln verbraucht Euer nächster Einsatz von 'Tritt der aufgehenden Sonne' oder 'Fasshieb' sämtliche Stapel und wird ein zweites Mal mit 100% Effektivität eingesetzt. Dieser Bonusangriff kann Effekte anstelle von 'Tigerklaue' mit verringerter Effektivität auslösen." }
