entries[418585] = { ["name"] = "Verwandlungsbombe", ["text"] = "150 Meter Reichweite\nSofort\nPips arglistige Magie verwandelt Spielercharaktere 12 Sek. lang in Enten und gewährt ihnen ' Glitschig ', was sie mit ' Hungrig ' belegt und es ihnen ermöglicht, ' Quak! ' und ' Putzen ' einzusetzen.\n\nBei Entfernung springt die Transformation auf andere Spielercharaktere innerhalb von 7 Metern über und belegt sie 12 Sek. lang mit ' Verwandlungsbombe '." }
