entries[418590] = { ["name"] = "Statische Aufladung", ["text"] = "Sofort 1.5 sek. Abklingzeit\nSolange Ihr Euch in der Nähe von Wänden befindet, sammelt Ihr 'Statische Aufladung', wodurch Ihr Elan wie durch 'Bodenkratzer' aufladet und pro Sekunde einen Stapel erhaltet, bis zu 10. Bei maximalen Stapeln wird 'Blitzerfüllung' verfügbar." }
