entries[419344] = { ["name"] = "Wildwuchs", ["text"] = "45 Meter Reichweite\nWirken in 1 sek. 8 sek. Abklingzeit\nHeilt bis zu 2 verletzte Verbündete innerhalb von 30 Metern um das Ziel im Verlauf von 7 Sek. um 97632 Gesundheit." }
entries[419345] = { ["name"] = "Schreckensgefährt der Vornacht", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren magischen Besen oder gibt ihn wieder frei! Dieser Besen passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an. Während der Schlotternächte ist dies ein Spontanzauber.\n\"Das bevorzugte Transportmittel der Familie Fenlow (insbesondere während der Schlotternächte).\"\nHandelsposten" }
